global_css:
/* UptimeFixer Safe Changes Manager - compact footer v1.2 */
.ufx-safe-footer,
.ufx-safe-footer * { box-sizing: border-box; }

.ufx-safe-footer {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #10202d;
  color: #f7fbff;
  font-family: inherit;
  border-top: 1px solid rgba(255,255,255,.07);
}

.ufx-safe-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: #c8f15a;
}

.ufx-safe-footer__inner {
  width: min(1320px, calc(100% - 56px));
  margin: 0 auto;
  padding: 46px 0 18px;
}

.ufx-safe-footer__top {
  display: grid;
  grid-template-columns: minmax(250px,1.05fr) minmax(320px,1.25fr) minmax(170px,.75fr) minmax(170px,.75fr);
  gap: 52px;
  align-items: start;
}

.ufx-safe-footer__brand {
  max-width: 330px;
}

.ufx-safe-footer__logo {
  display: inline-flex;
  align-items: center;
  margin: 0 0 20px;
  text-decoration: none !important;
}

.ufx-safe-footer__logo img,
.ufx-safe-footer__logo .custom-logo {
  display: block;
  width: auto;
  max-width: 205px;
  max-height: 58px;
  height: auto;
  object-fit: contain;
  background: #fff;
  padding: 7px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: 0 8px 22px rgba(0,0,0,.12);
}

.ufx-safe-footer__logo .custom-logo-link {
  display: inline-flex;
}

.ufx-safe-footer__logo-text {
  color: #fff;
  font-size: 22px;
  font-weight: 700;
}

.ufx-safe-footer__eyebrow {
  margin: 0 0 8px;
  color: #c8f15a;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .15em;
}

.ufx-safe-footer__brand h2 {
  margin: 0;
  color: #fff;
  font-size: 34px;
  line-height: 1.06;
  letter-spacing: -.035em;
  font-weight: 700;
}

.ufx-safe-footer__brand h2 span {
  color: #dafa86;
}

.ufx-safe-footer__intro {
  max-width: 320px;
  margin: 14px 0 0;
  color: rgba(239,245,250,.70);
  font-size: 14px;
  line-height: 1.65;
}

.ufx-safe-footer__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 40px;
  margin-top: 18px;
  padding: 9px 15px;
  border: 1px solid #c8f15a;
  border-radius: 999px;
  background: #c8f15a;
  color: #10202d !important;
  text-decoration: none !important;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  transition: transform .18s ease, background .18s ease;
}

.ufx-safe-footer__cta:hover {
  transform: translateY(-1px);
  background: #ddff86;
}

.ufx-safe-footer__cta-label {
  display: inline-flex;
  align-items: center;
}

.ufx-safe-footer__cta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  color: #126bff;
  line-height: 1;
  transform: translateY(-1px);
  transition: transform .18s ease, color .18s ease;
}

.ufx-safe-footer__cta-icon svg {
  display: block;
  width: 18px;
  height: 18px;
  overflow: visible;
}

.ufx-safe-footer__cta-icon svg path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ufx-safe-footer__cta:hover .ufx-safe-footer__cta-icon {
  transform: translate(2px,-3px);
  color: #0d5fe8;
}

.ufx-safe-footer__nav-section {
  min-width: 0;
}

.ufx-safe-footer__nav-section h3 {
  margin: 6px 0 18px;
  color: #fff;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.ufx-safe-footer__nav-section ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ufx-safe-footer__tools ul {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 30px;
}

.ufx-safe-footer__nav-section li {
  margin: 0 0 12px;
}

.ufx-safe-footer__nav-section a {
  display: inline-flex;
  color: rgba(235,242,248,.72);
  text-decoration: none !important;
  font-size: 14px;
  line-height: 1.4;
  transition: color .18s ease, transform .18s ease;
}

.ufx-safe-footer__nav-section a:hover {
  color: #c8f15a;
  transform: translateX(2px);
}

.ufx-safe-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,.10);
}

.ufx-safe-footer__bottom p {
  margin: 0;
  color: rgba(231,239,246,.58);
  font-size: 12px;
  line-height: 1.45;
}

.ufx-safe-footer__bottom a {
  color: #79aaff;
  text-decoration: none !important;
  font-weight: 600;
}

.ufx-safe-footer__bottom a:hover {
  color: #c8f15a;
}

.ufx-safe-footer__heart {
  color: #ff6570;
}

@media (max-width: 1080px) {
  .ufx-safe-footer__inner {
    width: min(100% - 44px,1320px);
    padding-top: 42px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1.15fr 1fr;
    gap: 36px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
    max-width: 600px;
  }

  .ufx-safe-footer__tools ul {
    column-gap: 24px;
  }
}

@media (max-width: 720px) {
  .ufx-safe-footer__inner {
    width: min(100% - 32px,1320px);
    padding: 38px 0 18px;
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr 1fr;
    gap: 32px 24px;
  }

  .ufx-safe-footer__brand {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__tools {
    grid-column: 1 / -1;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 31px;
  }

  .ufx-safe-footer__logo img,
  .ufx-safe-footer__logo .custom-logo {
    max-width: 190px;
  }

  .ufx-safe-footer__bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
    margin-top: 28px;
  }
}

@media (max-width: 460px) {
  .ufx-safe-footer__inner {
    width: min(100% - 28px,1320px);
  }

  .ufx-safe-footer__top {
    grid-template-columns: 1fr;
  }

  .ufx-safe-footer__brand,
  .ufx-safe-footer__tools {
    grid-column: auto;
  }

  .ufx-safe-footer__tools ul {
    grid-template-columns: 1fr 1fr;
    column-gap: 20px;
  }

  .ufx-safe-footer__brand h2 {
    font-size: 29px;
  }

  .ufx-safe-footer__cta {
    width: auto;
  }
}

/* UFX TARGETED HOME POLISH START */
/* Small, reversible homepage polish only. No layout/schema/URL changes. */
@media (min-width: 761px) {
  body.ufx-studio .studio-search {
    max-width: 560px;
    min-height: 58px;
    padding: 7px 8px 7px 18px;
    border: 1px solid #bcc7d1;
    border-radius: 14px;
    box-shadow: 0 8px 24px rgba(17,29,42,.07);
    transition: border-color .18s ease, box-shadow .18s ease, transform .18s ease;
  }

  body.ufx-studio .studio-search:focus-within {
    outline: 0;
    border-color: #2855ed;
    box-shadow: 0 0 0 4px rgba(40,85,237,.08), 0 10px 28px rgba(17,29,42,.08);
    transform: translateY(-1px);
  }

  body.ufx-studio .studio-search input[type=search] {
    padding: 11px 0;
    font-size: 15px;
  }

  body.ufx-studio .studio-search button {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: #2855ed;
    color: #fff;
    transition: transform .18s ease, background .18s ease;
  }

  body.ufx-studio .studio-search button:hover {
    background: #1745d8;
    transform: translateY(-1px);
  }

  body.ufx-studio .studio-quick {
    margin-top: 4px;
    padding: 14px;
    gap: 10px;
    border: 1px solid #deded8;
    border-radius: 14px;
    background: rgba(255,255,255,.72);
    box-shadow: 0 8px 24px rgba(17,29,42,.035);
  }

  body.ufx-studio .studio-quick > div:first-child {
    padding: 8px 10px;
  }

  body.ufx-studio .studio-quick h2 {
    font-size: 17px;
    margin-bottom: 4px;
  }

  body.ufx-studio .studio-quick > a {
    min-height: 72px;
    padding: 12px;
    border: 1px solid rgba(16,25,35,.05);
    border-radius: 10px;
    box-shadow: none;
  }

  body.ufx-studio .studio-quick > a:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 20px rgba(17,29,42,.06);
  }

  body.ufx-studio .studio-collection {
    border-radius: 14px;
    border-color: rgba(16,25,35,.07);
    box-shadow: 0 4px 14px rgba(17,29,42,.025);
  }

  body.ufx-studio .studio-collection:hover {
    transform: translateY(-3px);
    box-shadow: 0 14px 28px rgba(17,29,42,.07);
  }

  body.ufx-studio .studio-card-bottom {
    border-top: 1px solid rgba(16,25,35,.055);
  }

  body.ufx-studio .studio-more a {
    background: rgba(255,255,255,.58);
    transition: transform .18s ease, border-color .18s ease, color .18s ease, background .18s ease;
  }

  body.ufx-studio .studio-more a:hover {
    transform: translateY(-1px);
    background: #fff;
  }
}
/* UFX TARGETED HOME POLISH END */
